package diff

import (
	"sort"
	"strings"

	"github.com/hexops/gotextdiff"
	"github.com/hexops/gotextdiff/myers"
	"github.com/hexops/gotextdiff/span"

	"github.com/immuta/operations/apps/birdseye/internal/archive"
)

// Textual returns a FileDiff per file that differs between a and b,
// sorted by path. Files identical in both archives are not included.
func Textual(a, b archive.Module) []FileDiff {
	all := make(map[string]struct{})
	for k := range a.Files {
		all[k] = struct{}{}
	}
	for k := range b.Files {
		all[k] = struct{}{}
	}
	paths := make([]string, 0, len(all))
	for k := range all {
		paths = append(paths, k)
	}
	sort.Strings(paths)

	out := make([]FileDiff, 0, len(paths))
	for _, p := range paths {
		ab, aok := a.Files[p]
		bb, bok := b.Files[p]
		switch {
		case aok && bok:
			if string(ab) == string(bb) {
				continue
			}
			out = append(out, modifiedDiff(p, string(ab), string(bb)))
		case !aok && bok:
			out = append(out, addedDiff(p, string(bb)))
		case aok && !bok:
			out = append(out, removedDiff(p, string(ab)))
		}
	}
	return out
}

func modifiedDiff(path, oldText, newText string) FileDiff {
	edits := myers.ComputeEdits(span.URIFromPath(path), oldText, newText)
	unified := gotextdiff.ToUnified(path, path, oldText, edits)
	u := unified.String()
	adds, dels := countLines(u)
	return FileDiff{Path: path, Status: StatusModified, Unified: u, Adds: adds, Dels: dels}
}

func addedDiff(path, newText string) FileDiff {
	return FileDiff{
		Path:    path,
		Status:  StatusAdded,
		Unified: "+++ " + path + "\n" + prefixLines(newText, "+"),
		Adds:    countNonEmptyLines(newText),
	}
}

func removedDiff(path, oldText string) FileDiff {
	return FileDiff{
		Path:    path,
		Status:  StatusRemoved,
		Unified: "--- " + path + "\n" + prefixLines(oldText, "-"),
		Dels:    countNonEmptyLines(oldText),
	}
}

func prefixLines(s, prefix string) string {
	if s == "" {
		return ""
	}
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	var sb strings.Builder
	sb.Grow(len(s) + len(lines)*len(prefix))
	for _, l := range lines {
		sb.WriteString(prefix)
		sb.WriteString(l)
		sb.WriteByte('\n')
	}
	return sb.String()
}

func countNonEmptyLines(s string) int {
	if s == "" {
		return 0
	}
	n := strings.Count(s, "\n")
	if !strings.HasSuffix(s, "\n") {
		n++
	}
	return n
}

func countLines(unified string) (adds, dels int) {
	for _, line := range strings.Split(unified, "\n") {
		if len(line) == 0 {
			continue
		}
		switch line[0] {
		case '+':
			if !strings.HasPrefix(line, "+++") {
				adds++
			}
		case '-':
			if !strings.HasPrefix(line, "---") {
				dels++
			}
		}
	}
	return adds, dels
}
